/**
 * Resolved demos for the push and pull strength days.
 *
 * Generated by `node scripts/match-exercise-demos.ts`. The app reads this file
 * only — not the 1,324-row dataset, and not the GIF files.
 *
 * Instruction text is MIT, Copyright (c) 2026 Hasan Emir Yıldırım.
 * The pictures are not. They stay on the dataset host named by mediaBaseUrl.
 */
import catalog from './exercise-demos.json' with { type: 'json' };

export type ExerciseDemo = {
  routineName: string;
  via: 'fuzzy' | 'override';
  score: number;
  datasetId: string;
  datasetName: string;
  equipment: string;
  target: string;
  secondaryMuscles: string[];
  steps: string[];
  image: string;
  gif: string;
  attribution: string;
};

export type ExerciseDemoMiss = {
  routineName: string;
  equipment: string | null;
  reason: string;
  closest: { datasetId: string; datasetName: string; score: number } | null;
  override: string | null;
};

type ExerciseDemoCatalog = {
  source: string;
  sourceCommit: string;
  mediaBaseUrl: string;
  dataLicense: string;
  dataCopyright: string;
  dataLicenseNotice: string;
  mediaNotice: string;
  byName: Record<string, ExerciseDemo>;
  fuzzyMisses: ExerciseDemoMiss[];
  unmatched: ExerciseDemoMiss[];
};

const data = catalog as ExerciseDemoCatalog;

export const EXERCISE_DEMO_SOURCE = data.source;
export const EXERCISE_DEMO_SOURCE_COMMIT = data.sourceCommit;
export const EXERCISE_DEMO_MEDIA_BASE = data.mediaBaseUrl;
export const EXERCISE_DEMO_MEDIA_NOTICE = data.mediaNotice;
export const EXERCISE_DEMO_FUZZY_MISSES = data.fuzzyMisses;
export const EXERCISE_DEMO_UNMATCHED = data.unmatched;

function demoKey(name: string): string {
  return name.trim().toLowerCase();
}

export function lookupExerciseDemo(name: string): ExerciseDemo | null {
  return data.byName[demoKey(name)] ?? null;
}

export function unmatchedExerciseDemo(name: string): ExerciseDemoMiss | null {
  const key = demoKey(name);
  return data.unmatched.find((row) => row.routineName.toLowerCase() === key) ?? null;
}

export function exerciseDemoImageUrl(demo: ExerciseDemo): string {
  return data.mediaBaseUrl + demo.image;
}

export function exerciseDemoGifUrl(demo: ExerciseDemo): string {
  return data.mediaBaseUrl + demo.gif;
}
